local _, ns = ...
if ns.LOCALE ~= "deDE" then return end
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; beside Locales/deDE.lua.
L["WN100_1_TITLE"] = "Berufs-Seitenreiter"
L["WN100_1_TEXT"] = "Die Seitenreiter der Berufe tragen das klassische Aussehen und beginnen dort, wo die des Zauberbuchs beginnen, mit dem Reiter von What's Training darunter, der beim Überfahren mit ihnen erscheint."
L["WN100_2_TITLE"] = "Wer"
L["WN100_2_TEXT"] = "Ist \"Gruppensuche\" abgewählt, behält die Gruppensuche des Spiels ihren eigenen Wer-Reiter, und das Kontaktefenster zeigt keinen. Für Wer im Kontaktefenster schalte \"Wer-Reiter im Kontaktefenster\" unter Kontakte in den Optionen ein."
L["WN100_3_TITLE"] = "Fenster"
L["WN100_3_TEXT"] = "Sammlungen, Vermächtnis und die Gruppensuche sind jeweils unser klassisches Fenster oder das des Spiels, unsere Fenster öffnen sich neben den Seitenreitern eines Nachbarfensters, und im Bearbeitungsmodus ist ein Fenster, das ein anderes Addon bewegt, von Anfang an ausgegraut."
L["WN100_4_TITLE"] = "Kleinere Korrekturen"
L["WN100_4_TEXT"] = "What's Training im Zauberbuch trägt den schwarzen Marmor der Berufe, der Optionspfeil des Zauberbuchs bleibt bei ausgeblendeter Suche rechts, und der Knopf eines anderen Addons verdeckt das Schloss des Berufefensters nicht mehr."
L["WN99_1_TITLE"] = "Quests teilen"
L["WN99_1_TEXT"] = "Das Teilen von Quests im Questlog funktioniert wieder: deine Gruppe bekommt die Quest."
L["WN99_2_TITLE"] = "Ausklappmenüs in den Optionen"
L["WN99_2_TEXT"] = "Die Ausklappmenüs in den Optionen des Spiels zeigen mit einem texturierten eigenen Design keinen gestreckten Knopf mehr in sich."
L["WN99_3_TITLE"] = "Im Kampf"
L["WN99_3_TEXT"] = "Im Kampf springen die Aktionsleisten nicht mehr, wenn sich bei ausgeblendetem Mikromenü-Knopf ein Fenster öffnet, das aus dem Zauberbuch geöffnete Berufsbuch bleibt an der Stelle des Zauberbuchs ohne leere zweite Seite, und das Betrachten der Talente eines Spielers aus seinem Menü öffnet nur noch unser Fenster, ohne Fehler."
L["WN99_4_TITLE"] = "Chat"
L["WN99_4_TEXT"] = "Der Chat und seine Reiter verschwinden nicht mehr, wenn ein anderes Addon die Größe des Chats ändert."
L["WN99_5_TITLE"] = "Ausklappmenüs und What's Training"
L["WN99_5_TEXT"] = "Mit einem texturierten eigenen Design werden die Ausklappmenüs in unseren Optionen wieder ganz gezeichnet, und What's Training im Berufsbuch trägt den schwarzen Marmor des Zauberbuchs ohne Linien über der Liste."
L["WN98_1_TITLE"] = "Taschensymbole auf leeren Plätzen"
L["WN98_1_TEXT"] = "In Eine Tasche zeigt jeder leere Platz jetzt ein blasses Symbol der Tasche, zu der er gehört, so sind die Plätze eines Köchers leicht zu finden. Schalte sie in den Optionen (/fcui) ein: Eine Tasche, unter Taschen. Schlichte leere Plätze, direkt darunter, macht sie wieder alle gleich."
L["WN98_2_TITLE"] = "Klassenfarben im Schlachtfeld"
L["WN98_2_TEXT"] = "Namensplaketten feindlicher Spieler zeigen jetzt ihre Klassenfarbe in Schlachtfeldern und Dungeons, wo das Spiel ihre Klasse verbirgt und sie rot waren."
L["WN98_3_TITLE"] = "Taschen bleiben, wo sie sind"
L["WN98_3_TEXT"] = "Im Bearbeitungsmodus verschobene Taschen bleiben jetzt, wo du sie ablegst. Taschen, die du vor dieser Version platziert hast, bleiben an ihrem Platz."
L["WN98_4_TITLE"] = "Fenster im Vordergrund"
L["WN98_4_TEXT"] = "Ein Fenster, das du über das Questlog oder das Zauberbuch ziehst, liegt jetzt darüber, und die Symbole des Zauberbuchs scheinen nicht mehr durch."
L["WN98_5_TITLE"] = "Reiter der Gruppensuche"
L["WN98_5_TEXT"] = "Die Gruppensuche und ein Fenster, das ein anderes Addon über seine Seitenreiter öffnet, teilen sich jetzt einen Platz: Beim Wechsel der Reiter springt nichts mehr, und Ziehen eines der beiden verschiebt beide."
L["WN97_1_TITLE"] = "Keine Lücke auf Höchststufe"
L["WN97_1_TEXT"] = "Auf Höchststufe, ohne Erfahrungs- oder Rufleiste, sitzen die Leisten über der Hauptleiste jetzt auf der schmalen Leiste, wo die Erfahrung war, wie in Era."
L["WN97_2_TITLE"] = "Vermächtnisherausforderungen"
L["WN97_2_TEXT"] = "Die Liste der Herausforderungen ordnet ihre Abschnitte jetzt wie das Fenster des Spiels, und die Suche findet jedes Wort, das eine Herausforderung zeigt, von ihren Abschnitten bis zu ihren Schritten."
L["WN97_3_TITLE"] = "Seitenreiter anderer Addons"
L["WN97_3_TEXT"] = "Seitenreiter, die andere Addons der Gruppensuche hinzufügen, etwa der von LFG Forever, sehen jetzt wie unsere aus und reihen sich darunter ein."
L["WN96_1_TITLE"] = "Beutewürfe wie in Era"
L["WN96_1_TEXT"] = "/loot öffnet das Fenster für Beutewürfe aus Era: jeder Gegenstand mit Gewinner und Wurf, und + bei einem Gegenstand zeigt alle Würfe. Der Reiter darunter ändert die Höhe, die Ecke die Größe in beide Richtungen."
L["WN96_2_TITLE"] = "Offline erscheinen"
L["WN96_2_TEXT"] = "Das Statusmenü im klassischen Kontaktfenster bietet jetzt Offline erscheinen, neben Verfügbar, Abwesend und Beschäftigt."
L["WN96_3_TITLE"] = "Soziales abgewählt"
L["WN96_3_TEXT"] = "Wer Soziales auf der Seite Alle Fenster abwählt, bekommt jetzt das Kontaktfenster des Spiels, ohne unsere Reiter."
L["WN95_1_TITLE"] = "Eine Tasche je Profil"
L["WN95_1_TEXT"] = "Profile merken sich jetzt die Option Eine Tasche: Charaktere mit verschiedenen Profilen behalten ihre eigene Taschenansicht. Bisher galt eine Änderung an einem Charakter für alle. Schalte sie in jedem Profil, das sie nutzen soll, in den Optionen (/fcui) ein: Eine Tasche, unter Taschen."
L["WN95_2_TITLE"] = "Werte im Kampf"
L["WN95_2_TEXT"] = "Die Werte im Charakterfenster sind nicht mehr leer, wenn es zum ersten Mal im Kampf geöffnet wird, und Attribute, Gesundheit, Rüstung, kritische Trefferchance, Tempo und Ausweichen folgen im Kampf den Stärkungszaubern."
L["WN94_1_TITLE"] = "Beute verteilen"
L["WN94_1_TEXT"] = "Das Verteilen von Beute an die Gruppe klappt wieder mit dem klassischen Beutefenster: Ein Klick auf einen Gegenstand zeigt die Liste der Spieler, im Stil von Era unter dem Gegenstand."
L["WN93_1_TITLE"] = "Namensplaketten-Stile"
L["WN93_1_TEXT"] = "Klassisch steht jetzt in der Stilliste der Namensplaketten des Spiels (Optionen, Namensplaketten). Wählst du einen Stil des Spiels, schalten sich unsere Namensplaketten aus und dieser Stil erscheint; Klassisch holt unsere zurück."
L["WN93_2_TITLE"] = "Beuteverlauf"
L["WN93_2_TEXT"] = "Das Beuteverlaufsfenster (/loot) trägt den klassischen Rahmen in deinem Thema. Zieh an seiner Ecke, um es in beide Richtungen zu ändern; ein Rechtsklick auf die Ecke gibt ihm seine eigene Größe zurück."
L["WN93_3_TITLE"] = "Hintergrund der Haltungsleiste"
L["WN93_3_TEXT"] = "Der Hintergrund hinter der Haltungs- und Begleiterleiste folgt dem Thema der Aktionsleisten, wie die eigene Grafik der Leiste."
L["WN93_4_TITLE"] = "Herstellungsanzahl"
L["WN93_4_TEXT"] = "Ein Klick in das Anzahlfeld des klassischen Berufsfensters markiert die Zahl, sodass Tippen sie ersetzt, wie in Era."
L["WN92_1_TITLE"] = "Haltungs- und Begleiterleiste"
L["WN92_1_TEXT"] = "Haltungs-, Begleiter- und Besessenheitsleiste sitzen, wo Era sie hinsetzt: oben auf der Hauptleiste auf Eras eigenem Hintergrund oder knapp über Leiste 2, wenn sie an ist. Zieh eine im Bearbeitungsmodus, um sie selbst zu platzieren."
L["WN92_2_TITLE"] = "Totemleiste"
L["WN92_2_TEXT"] = "Die Totemleiste des Schamanen sitzt am Platz der Haltungsleiste oben auf der Hauptleiste und bleibt nach jedem Laden dort."
L["WN92_3_TITLE"] = "Aktionsleisten"
L["WN92_3_TEXT"] = "Schaltest du Leiste 2 oder Leiste 3 aus, bleibt die andere, wo sie war."
L["WN92_4_TITLE"] = "Berufsmakros"
L["WN92_4_TEXT"] = "Ein Makro kann im klassischen Berufsfenster auf Herstellen drücken, etwa ein Schnellverzauberungsmakro: /run ClassicUIForeverTradeSkill.CreateButton:Click()"
L["WN91_1_TITLE"] = "Questverfolgung"
L["WN91_1_TEXT"] = "Kommen entfernte Quests zurück in die Questverfolgung? Das ist die automatische Questverfolgung des Spiels. Hak unter Quests (/fcui) Automatische Questverfolgung ab, dann bleiben sie draußen."
L["WN91_2_TITLE"] = "Schlachtzugsfenster"
L["WN91_2_TEXT"] = "Das Gruppenfenster am linken Bildschirmrand kann verborgen bleiben, bis du mit der Maus darüberfährst. Schalte es in den Optionen (/fcui) ein: Schlachtzugsfenster bei Mausberührung, unter Einheitenfenster."
L["WN90_1_TITLE"] = "Questfarben"
L["WN90_1_TEXT"] = "Alle Quests gelb? Dann ist die Spieleinstellung für Questschwierigkeitsfarben aus. Sie steht jetzt auch in den Optionen (/fcui): hak unter Quests Questschwierigkeitsfarben an."
L["WN90_2_TITLE"] = "Reiter Begleiter"
L["WN90_2_TEXT"] = "Er zeigt die Werte, die Begleiter wirklich haben: Gesundheit, Geschwindigkeit, kritische Trefferchance, Tempo, Angriffskraft, Schaden, Verteidigung und Rüstung."
L["WN90_3_TITLE"] = "Taschen"
L["WN90_3_TEXT"] = "Taschen, die du im Bearbeitungsmodus auf die klassische Leiste ziehst, bleiben nach dem Ausloggen dort, und ein Lua-Fehler, den manche Addons beim Auffrischen der Taschen auslösten, ist behoben."
L["WN90_4_TITLE"] = "Sammlungen"
L["WN90_4_TEXT"] = "Unter Vorlagen passt die Vorschau deinen ganzen Charakter ein, und eine andere Vorlage am selben Platz behält die Kamera, wo du sie gelassen hast."
L["WN90_5_TITLE"] = "Questlog"
L["WN90_5_TEXT"] = "Es wird nicht mehr langsam, während ein anderes Addon Gegenstandsdaten lädt."
L["WN89_1_TITLE"] = "Kein Erfolgskästchen mehr"
L["WN89_1_TEXT"] = "Das Kästchen des Spiels, das bei einem abgeschlossenen Erfolg (auf Forever einer Vermächtnisherausforderung) oder einem Schritt dazu aufspringt, ist weg, denn 1.x hatte keines. Um es zurückzuholen, schalte es in den Optionen (/fcui) ein: hak unter Sonstiges Erfolgsmeldung an."
L["WN89_2_TITLE"] = "Reiter Fertigkeiten"
L["WN89_2_TEXT"] = "Sein unterer Bereich bleibt nicht mehr stehen, wenn das Charakterfenster auf einem anderen Reiter öffnet."
L["WN88_1_TITLE"] = "Begleiter"
L["WN88_1_TEXT"] = "Einen anderen Begleiter zu beschwören, lässt das Spiel nicht mehr kurz einfrieren."
L["WN88_2_TITLE"] = "Questlog"
L["WN88_2_TEXT"] = "Der Klang beim Abbrechen einer Quest ertönt erst, wenn du Ja wählst."
L["WN88_3_TITLE"] = "Berufe"
L["WN88_3_TEXT"] = "Das Berufebuch rechnet Ausrüstung wie eine Angelrute in den Bonus jeder Fertigkeit ein."
L["WN87_1_TITLE"] = "Einheiten-Tooltips"
L["WN87_1_TEXT"] = "Die Zeile mit dem Hinweis auf Rechtsklick für die Rahmeneinstellungen fehlt in den Tooltips der Einheitenfenster, wie in Era. Um sie wieder zu sehen, schalte in den Optionen (/fcui) unter Einheitenfenster „Rechtsklick-Hinweis ausblenden“ aus."
L["WN87_2_TITLE"] = "Taschen"
L["WN87_2_TEXT"] = "Der Rucksack behält sein klassisches Bild, wenn sich Taschen ändern."
L["WN87_3_TITLE"] = "Charakterfenster"
L["WN87_3_TEXT"] = "Die Zeilen für Trefferchance zeigen wieder ihren Tooltip."
L["WN87_4_TITLE"] = "Händler"
L["WN87_4_TEXT"] = "Die Reparaturknöpfe zeigen die Symbole aus Era."
L["WN87_5_TITLE"] = "EP-Leiste"
L["WN87_5_TEXT"] = "Die EP-Leiste sitzt wie in Era und ist genauso hoch."
L["WN86_1_TITLE"] = "Aktionsleisten-Addons"
L["WN86_1_TEXT"] = "Mit einem Aktionsleisten-Addon, das die Leisten des Spiels übernimmt, behalten seine Leisten ihre Tasten und ihr Aussehen, Masque-Skins eingeschlossen, und Ausloggen und Spiel verlassen im Spielmenü funktionieren wieder."
L["WN86_2_TITLE"] = "Klassische Leiste ausgeschaltet"
L["WN86_2_TEXT"] = "Begleiter- und Haltungstasten sowie die Charaktertaste bekommen ihr eigenes Aussehen zurück."
L["WN85_1_TITLE"] = "Optionsfenster des Spiels"
L["WN85_1_TEXT"] = "Das Optionsfenster des Spiels senkt die Bildrate nicht mehr, solange es offen ist."
L["WN85_2_TITLE"] = "Talente"
L["WN85_2_TEXT"] = "Ein Talent, das erst mit genug Punkten in seinem Baum frei wird, nennt wie in Era in Rot, wie viele es braucht."
L["WN85_3_TITLE"] = "EP-Leiste"
L["WN85_3_TEXT"] = "Die Segmentstriche des Spiels erscheinen nicht mehr über der EP-Leiste, wenn du dich im Kampf einloggst."
L["WN85_4_TITLE"] = "Berufe"
L["WN85_4_TEXT"] = "Das Berufebuch hält die Zauber jedes Berufs beieinander, wenn es im Kampf geöffnet wird, und mit TradeSkillMaster springt das Berufsfenster am Ende eines Kampfes nicht mehr nach rechts."
L["WN84_1_TITLE"] = "Händler- und Lehrerfenster"
L["WN84_1_TEXT"] = "Die Fenster von Händlern und Lehrern lassen sich jetzt verschieben und in der Größe ändern. Klicke auf das Schloss neben der Schließen-Schaltfläche und ziehe dann das Fenster oder seine Ecke. Sie teilen Platz und Größe mit den Quest- und Gesprächsfenstern, und in ClassicUI Forever Fenster sind Fenster mit gemeinsamem Platz eine Zeile und ein Rahmen."
L["WN84_2_TITLE"] = "Zielverfolgung und Questeinstellungen der Karte"
L["WN84_2_TEXT"] = "Questtitel in der klassischen Zielverfolgung, im Questlog und in den Questlisten der Karte folgen der Karteneinstellung Einfärbung der Questschwierigkeit (schlicht, wenn sie aus ist), und diese Einstellung sowie Queststufen anzeigen wirken sofort, ohne Neuladen."
L["WN84_3_TITLE"] = "Korrekturen"
L["WN84_3_TEXT"] = "Ein Questtitel in der klassischen Zielverfolgung behält seine Farbe, nachdem die Maus ihn verlässt, die Bildlaufleisten der vereinten klassischen Karte sitzen an ihrem Platz, wenn die Karte im Fenster ist, die Kartentaste schließt diese Karte auf jedem Charakter, und die Minikartenschaltfläche bleibt in der Tasche von MinimapButtonBag Reborn."
L["WN84_4_TITLE"] = "Reiter Fertigkeiten"
L["WN84_4_TEXT"] = "Steigt im Kampf eine Fertigkeit, verursacht das keinen Fehler mehr, während der Reiter Fertigkeiten eine Waffenfertigkeit zeigt."
L["WN83_1_TITLE"] = "Fertigkeiten und Auktionshaus"
L["WN83_1_TEXT"] = "Der Reiter Fertigkeiten verursacht keinen Fehler mehr bei Charakteren mit einem Bonus auf Verteidigung, und die Gebotsschaltfläche im Auktionshaus verdeckt nicht mehr das Ende des Kupferfelds."
L["WN83_2_TITLE"] = "Schlachtzugsfenster und Controller"
L["WN83_2_TEXT"] = "Der geschlossene Reiter des Schlachtzugsfensters sitzt am Bildschirmrand, wenn du im Kampf einer Gruppe beitrittst, und die Gamepad-Optionen zeigen die Ansicht- und Menü-Symbole deines Controllers."
L["WN82_1_TITLE"] = "Quest teilen mit Karte im Vollbild"
L["WN82_1_TEXT"] = "Wer die Weltkarte im Vollbild nutzt: Nach dem Teilen einer Quest aus dem Questlog bleibt die Karte nicht mehr offen."
L["WN82_2_TITLE"] = "Quest teilen"
L["WN82_2_TEXT"] = "Quest teilen im Questlog teilt die Quest, statt auf die Weltkarte zu verweisen."
L["WN81_1_TITLE"] = "Herstellungskosten und Gewinn"
L["WN81_1_TEXT"] = "Mit Auctionator zeigt das klassische Berufsfenster über den Reagenzien, was ein Rezept kostet und einbringt, und bei offenem Auktionshaus eine Suchen-Schaltfläche für die Reagenzien."
L["WN81_2_TITLE"] = "Klassenfarben für Freunde oder Gegner"
L["WN81_2_TEXT"] = "Befreundete Spieler und Gegnerische Spieler sind eigene Kästchen unter den Klassenfarben der Namensplaketten, dem Namensfeld in Klassenfarbe und der Gesundheit in Klassenfarbe: Klassenfarben gehen so auch nur für eine Seite. Die Klassenfarben-Optionen selbst sind standardmäßig aus: schalte sie in den Optionen (/fcui) ein."
L["WN81_3_TITLE"] = "Autolauf am Controller"
L["WN81_3_TEXT"] = "Im klassischen Layout liegt Autolauf standardmäßig auf dem Druck des linken Sticks, und eine für Autolauf oder Chat gewählte Taste funktioniert auch auf einem Stick, mit dem der Cursor klickt."
L["WN81_4_TITLE"] = "Korrekturen"
L["WN81_4_TEXT"] = "Die Liste von What's Training im zweigeteilten Berufsfenster liegt auf einem einzigen Hintergrund, und die Gesundheits- und Fokusleiste des Begleiterfensters füllen ihre Fächer."
L["WN80_1_TITLE"] = "Controller im klassischen Layout (in Arbeit)"
L["WN80_1_TEXT"] = "Spiele die klassischen Leisten mit einem Controller, während die Gamepad-Oberfläche des Spiels aus ist: Steuerkreuz und Aktionstasten lösen Aktionsleiste 1 aus, mit gehaltenem Trigger die anderen Leisten. Standardmäßig aus; beim ersten Benutzen eines Controllers fragt ein Fenster, und es steht in den Optionen (/fcui) unter Gamepad. Noch in Arbeit: Taschen, Karte und Menüs brauchen vorerst den Cursor des Spiels."
L["WN80_2_TITLE"] = "Schlachtzugsfenster im Kampf"
L["WN80_2_TEXT"] = "Das Schlachtzugs- und Gruppenfenster behält seine Zeilen an ihrem Platz, wenn sich die Gruppe im Kampf ändert, und sein Ausziehreiter verschwindet nicht mehr, wenn du das Fenster im Kampf schließt."
L["WN80_3_TITLE"] = "Begleiterausbildung"
L["WN80_3_TEXT"] = "Das Lehrerfenster behält keine alte Liste mehr, sodass Fähigkeiten, die dein Begleiter schon kennt, nicht als erlernbar stehen bleiben."
L["WN79_1_TITLE"] = "Schlachtzugsfenster im Kampf"
L["WN79_1_TEXT"] = "Das Schlachtzugs- und Gruppenfenster verursacht keinen Fehler mehr, wenn sich deine Gruppe im Kampf ändert, etwa wenn ein Gruppenmitglied eine Stufe aufsteigt. Es zieht nach, sobald der Kampf endet."
L["WN78_1_TITLE"] = "Klassisches Schlachtzugsfenster"
L["WN78_1_TEXT"] = "Das Schlachtzugs- und Gruppenfenster am linken Bildschirmrand hat das klassische Aussehen und die klassische Reihenfolge, und alle Bedienelemente des Spiels sind noch darin. Sein Weltmarkierungsknopf lässt die Zielsymbole den Boden markieren."
L["WN78_2_TITLE"] = "Rand des Schlachtzugsfensters"
L["WN78_2_TEXT"] = "Geschlossen zeigt das Fenster nur seinen Pfeilreiter. Rand des Schlachtzugsfensters, wenn geschlossen, lässt seinen Rahmen am Bildschirmrand stehen, wie in Era. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Einheitenfenster ein."
L["WN78_3_TITLE"] = "Kleine Korrekturen"
L["WN78_3_TEXT"] = "Das Beutefenster öffnet sofort und springt nicht mehr, wenn du mit vollen Taschen einen Gegenstand anklickst. Die Knöpfe des Gildenreiters und des Communityfensters bleiben nicht mehr anklickbar, nachdem ihr Fenster im Kampf geschlossen wurde."
L["WN77_1_TITLE"] = "Suche beim Lehrer"
L["WN77_1_TEXT"] = "Das Lehrerfenster hat neben dem Filter ein Suchfeld. Es zeigt nur die Zauber und Rezepte, deren Name die Wörter enthält. Suchfeld unter Lehrerfenster in den Optionen (/fcui) schaltet es aus."
L["WN77_2_TITLE"] = "What's Training in eigenem Fenster"
L["WN77_2_TEXT"] = "Der Lern-Reiter des Zauberbuchs kann das eigene Fenster von What's Training statt einer Seite im Buch öffnen; das Fenster schließt sich mit dem Buch. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Zauberbuch ein."
L["WN77_3_TITLE"] = "Gildennamen in Klassenfarbe"
L["WN77_3_TEXT"] = "Namen in der Gildenliste können in ihrer Klassenfarbe erscheinen. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Gildenliste ein."
L["WN77_4_TITLE"] = "Klassische Bank"
L["WN77_4_TEXT"] = "Die Bank hat die klassischen Platzplatten und Nieten im klassischen Abstand, in einem kürzeren Fenster."
L["WN77_5_TITLE"] = "Suchfelder"
L["WN77_5_TEXT"] = "Die Suchfelder des Questlogs und der Berufe haben das klassische Aussehen der Eingabefelder."
L["WN77_6_TITLE"] = "Hinweise über dem Chat"
L["WN77_6_TEXT"] = "Freundesmeldungen und der Hinweis zur Weltaktualisierung stehen über den Reitern des Chats. Bei einem höheren Chat hatten sie seinen Text und seine Reiter verdeckt."
L["WN77_7_TITLE"] = "Kleine Korrekturen"
L["WN77_7_TEXT"] = "Forever Quest Tint deckt die ganze Questseite auf der Karte ab, nicht nur einen Streifen unter dem Titel. Das Schließen einer Bank oder eines Händlers schiebt offene Taschen nicht mehr kurz beiseite, und /fstack listet die versteckten Hilfsrahmen des Addons nicht mehr auf."
L["WN76_1_TITLE"] = "Suche im Questlog"
L["WN76_1_TEXT"] = "Das Questlog mit Doppelseite hat ein Suchfeld in der Kopfzeile. Es listet die Quests, deren Name oder Zone die Wörter enthält."
L["WN76_2_TITLE"] = "Nach Schwierigkeit sortieren"
L["WN76_2_TEXT"] = "Alle Rezepte eines Berufs in einer Liste, zuerst orange, dann gelb, grün und grau. Schalte es im Filtermenü eines Berufsfensters oder in den Optionen (/fcui) unter Berufe ein."
L["WN76_3_TITLE"] = "Klassische Schließknöpfe"
L["WN76_3_TEXT"] = "Die Gildenbank und die Karte des Flugmeisters haben das klassische X."
L["WN75_1_TITLE"] = "Tooltip eines Gegenstandslinks"
L["WN75_1_TEXT"] = "Das X am Tooltip eines Gegenstandslinks ist das klassische, an seiner klassischen Stelle."
L["WN75_2_TITLE"] = "Begleiterfähigkeiten am Mauszeiger"
L["WN75_2_TEXT"] = "Nach einem Begleiterwechsel wird eine Begleiterfähigkeit, deren Kopie das Spiel nicht behält, einmal abgelegt statt immer wieder. Bei manchen Begleitern hatte das Symbole an den Mauszeiger gelegt und das Spiel ausgebremst."
L["WN74_1_TITLE"] = "Trainingsseite im Zauberbuch"
L["WN74_1_TEXT"] = "Die Trainingsseite des Zauberbuchs funktioniert mit What's Training 11.3. Mit dieser Version öffnete der Reiter das eigene Fenster von What's Training statt der Liste im Buch."
L["WN74_2_TITLE"] = "Quest teilen aus dem Questlog"
L["WN74_2_TEXT"] = "Quest teilen im Questlog teilt auch Quests außerhalb der Zone, in der du stehst, Dungeonquests eingeschlossen, und lässt die Weltkarte danach geschlossen."
L["WN73_1_TITLE"] = "Lernen im Berufsfenster"
L["WN73_1_TEXT"] = "Mit installiertem What's Training hat das Fenster eines Berufs zwei seitliche Reiter: der untere listet, was sein Lehrer dir beibringen kann, der obere kehrt zum Beruf zurück. Die Lern-Reiter tragen die eigenen Symbole von What's Training, auch im Zauberbuch."
L["WN73_2_TITLE"] = "Plündern im Kampf"
L["WN73_2_TEXT"] = "Das Plündern eines Leichnams im Kampf öffnet das Beutefenster. Ab dem zweiten Plündern einer Sitzung hatte das Spiel es mit der Meldung verweigert, eine Interface-Aktion sei wegen eines Addons fehlgeschlagen."
L["WN73_3_TITLE"] = "Zauberbuch"
L["WN73_3_TEXT"] = "Die Mikromenü-Schaltfläche und die Taste schließen das Buch von der What's-Training-Seite aus, und ein dort geschlossenes Buch öffnet sich wieder. Im Kampf öffnet sich das Buch am Anfang der Fensterreihe; es hatte sich weit rechts geöffnet, wenn die Karte zu Kampfbeginn offen war."
L["WN73_4_TITLE"] = "Plakettengröße pro Charakter"
L["WN73_4_TEXT"] = "Gleiche Größe nah und fern übernimmt beim Einloggen die Wahl jedes Charakters. Es wirkte erst, nachdem das Kästchen bei diesem Charakter umgeschaltet wurde. Schalte es in den Optionen (/fcui) unter Namensplaketten ein."
L["WN72_1_TITLE"] = "Anprobe"
L["WN72_1_TEXT"] = "Die Anprobe öffnet in der Größe von 1.x. Für die größere Anprobe späterer Clients schalte Große Anprobe in den Optionen (/fcui) unter Alle Fenster ein; unsere Fenster machen daneben Platz für ihre Seitenleisten."
L["WN72_2_TITLE"] = "Mikromenü ausblenden"
L["WN72_2_TEXT"] = "Das Mikromenü kann wie die Aktionsleisten verblassen: Verblasste Deckkraft oder Nur bei Mausberührung in seinem Bearbeitungsmodus-Dialog setzen und es mit den verblassten Leisten verknüpfen."
L["WN72_3_TITLE"] = "Gildenfenster"
L["WN72_3_TEXT"] = "Mitglied hinzufügen, Gildeninformation und das Rechtsklick-Menü eines Mitglieds laufen über die spieleigenen Buttons und Menüs, sodass Einladen, Bearbeiten der Information, Entfernen, Befördern und Degradieren funktionieren."
L["WN72_4_TITLE"] = "Seitenreiter Wer"
L["WN72_4_TEXT"] = "Der Seitenreiter Wer der Gruppensuche ist für alle ausgeblendet. Schalte Seitenreiter Wer ausblenden in den Optionen (/fcui) unter Soziales aus, um ihn zurückzuholen."
L["WN72_5_TITLE"] = "Größe der Namensplaketten"
L["WN72_5_TEXT"] = "Gleiche Größe nah und fern hält die Plaketten auf einer Größe wie in Classic Era, jetzt über die spieleigenen Einstellungen und pro Charakter gespeichert, außerhalb der Profile. Schalte es in den Optionen (/fcui) unter Namensplaketten ein."
L["WN72_6_TITLE"] = "Korrekturen"
L["WN72_6_TEXT"] = "Ein langer Gildenname endet mit Punkten vor der Zonenspalte, das Lehrerfenster scrollt eine lange Beschreibung, Strg-Klick auf eine Questbelohnung öffnet die Anprobe, die Buttons der Totemleiste tragen den klassischen Look, die Gruppenzahl einer Quest bleibt auch ohne Queststufen, und die Listen von What's Training liegen auf einer Seite des Zauberbuchs mit einem Reiter Berufe daneben."
L["WN71_1_TITLE"] = "Totemleiste bleibt an Ort und Stelle"
L["WN71_1_TEXT"] = "Eine im Bearbeitungsmodus an eine Aktionsleiste geheftete Leiste, etwa die Totemleiste des Schamanen, behält ihren Platz nach dem Bearbeitungsmodus und nach einem Neuladen."
L["WN71_2_TITLE"] = "Minimap-Button-Leisten"
L["WN71_2_TEXT"] = "Eine Minimap-Button-Leiste eines anderen Addons lässt sich mit ClassicUI Forever wieder verschieben."
L["WN71_3_TITLE"] = "Bedrohung in Prozent"
L["WN71_3_TEXT"] = "Die Bedrohung in Prozent über Ziel und Fokus endet bei 999 %, wie in Classic Era."
L["WN70_1_TITLE"] = "Verknüpftes Verblassen"
L["WN70_1_TEXT"] = "Verblasste Aktionsleisten können gemeinsam zurückkommen: Aktiviert im Bearbeitungsmodus bei verblassten Leisten Mit anderen verblassten Leisten verknüpft, dann zeigt die Maus über einer davon alle (#255)."
L["WN70_2_TITLE"] = "Leuchten beim Verzaubern"
L["WN70_2_TEXT"] = "Das goldene Leuchten des Spiels nach einem Wetzstein, Öl oder einer Verzauberung ist aus, denn Classic Era hatte keines. Um es zurückzuholen, schalte es in den Optionen (/fcui) ein: Goldenes Leuchten beim Verzaubern unter Charakterfenster. Es läuft jetzt am Rahmen des Fensters entlang (#262)."
L["WN70_4_TITLE"] = "Titel-Reiter"
L["WN70_4_TEXT"] = "Die Seitenleiste des Charakterfensters hat wieder den Reiter Titel (#261). Talentsymbole füllen ihre Felder wie in Classic Era (#260)."
L["WN70_3_TITLE"] = "Beutefenster mit dem Controller"
L["WN70_3_TEXT"] = "Mit dem Controller bewegt sich das Steuerkreuz durch die Gegenstände im Beutefenster (#264)."
L["WN69_1_TITLE"] = "Unsere Fenster mit dem Controller"
L["WN69_1_TEXT"] = "Mit der Gamepad-Oberfläche funktionieren das klassische Zauberbuch, die Talente, das Questlog, die Sammlungen, das Legacy-Fenster und die eine Tasche mit dem Controller: Das Steuerkreuz bewegt, A wählt, B schließt, und die Tasten stehen unter dem Fenster. Zauberbuch und Talente öffnen sich wieder als eigene Fenster. Im Questlog rollt die Liste mit, und Y öffnet die Karte."
L["WN69_2_TITLE"] = "Zauber aus dem Zauberbuch belegen"
L["WN69_2_TEXT"] = "Mit dem Controller drückst du im klassischen Zauberbuch X auf einen Zauber und dann die Taste dafür; halte LT oder RT für die seitlichen Gruppen, wie im Buch des Spiels. Y öffnet den Aktionsleisten-Editor des Spiels."
L["WN69_3_TITLE"] = "Berufsreiter ausgeblendet"
L["WN69_3_TEXT"] = "Die Reiter neben dem Berufsfenster sind ausgeblendet, denn Classic Era hatte keine. Um sie zurückzuholen, schalte sie in den Optionen (/fcui) ein: wähle unter Berufebuch Berufsreiter: beim Darüberfahren oder immer sichtbar. Die Liste der noch erlernbaren Rezepte von What's Training öffnet sich über einen Reiter neben dem Buch (#260)."
L["WN69_4_TITLE"] = "Kleinere Änderungen"
L["WN69_4_TEXT"] = "Das Chatfenster bleibt an seinem Platz, wenn ein anderes Addon es an der Oberkante in der Größe ändert (#247). Mit dem Controller blättern die Reiter Zauberbuch und Sammlungen im Berufsfenster an Ort und Stelle um, und der Rahmen um das Charakterfenster passt."
L["WN68_1_TITLE"] = "Doppelspezialisierungs-Reiter am Talentfenster"
L["WN68_1_TEXT"] = "Die Reiter der beiden Spezialisierungen laufen an der Kante des Talentfensters entlang, wie in Classic. Klick einen, um dir diese Spezialisierung anzusehen."
L["WN68_2_TITLE"] = "Der Text der Weltkarte in Spielgröße"
L["WN68_2_TEXT"] = "Im Classic-Stil der Kopfzeile waren Kopfzeile, Questleiste und Kartenoptionen der Karte im Fenster nur 70 % so groß wie der Spieltext. Jetzt haben sie Spielgröße, die Questleiste hat ihre volle Breite, und die Beschriftungen Kontinent und Zone stehen neben ihren Auswahlmenüs."
L["WN68_3_TITLE"] = "Quests auf Pergament in der Kartenleiste"
L["WN68_3_TEXT"] = "Die Questleiste der Karte listet Quests auf dem Pergament des Spiels. Für den dunklen Stein hak unter Weltkarte Liste auf dem Pergament des Spiels ab."
L["WN68_4_TITLE"] = "Addontasten am Ring behalten"
L["WN68_4_TEXT"] = "Bei eingeschaltetem Addontasten sammeln listet Am Ring lassen jede Addontaste auf; hak die an, die am Ring bleiben, während die übrigen in die Tasche wandern. Addontasten sammeln ist standardmäßig aus; schalte es in den Optionen (/fcui) unter Minikarte ein."
L["WN68_5_TITLE"] = "Kein Kästchen Neues Rezept erlernt mehr"
L["WN68_5_TEXT"] = "Das Kästchen des Spiels, das aufspringt, wenn ein Beruf euch etwas beibringt, ist weg, denn 1.x hatte keines. Um es zurückzuholen, schalte es in den Optionen (/fcui) ein: hak unter Sonstiges Fertigkeitsmeldung an."
L["WN68_6_TITLE"] = "Kleinere Änderungen"
L["WN68_6_TEXT"] = "Ein Talent unter seinem höchsten Rang ist grün, ob ihr Punkte zu vergeben habt oder nicht, wie in Classic Era. Die Listen des Sozialfensters zählen ihre Zeilen ganz (#232), und die Zeile Schadenszahlen ist weg, da sie nur die Einstellung des Spiels spiegelte."
L["WN67_1_TITLE"] = "Minimap-Teile bleiben auf der Minikarte"
L["WN67_1_TEXT"] = "Jedes Minimap-Teil in ClassicUI Forever Windows hat ein Kästchen Auf der Minikarte bleiben. Angehakt behält das Teil seinen Platz auf der Minikarte. Abgehakt lässt es sich überallhin ziehen."
L["WN67_2_TITLE"] = "Das Optionsfenster folgt dem Theme"
L["WN67_2_TEXT"] = "Sein Rahmen und die Teile aus Classic Era tragen den dunklen, bronzenen oder eigenen Look, und im klassischen Look bleibt kein Bronze an seinen Rändern."
L["WN67_3_TITLE"] = "Plätze und Kopfleiste der einen Tasche"
L["WN67_3_TEXT"] = "Leere Plätze zeigen kein Taschensymbol, das Suchfeld reicht bis zum Aufräumen-Knopf, und die Kopfleiste ist vollständig."
L["WN67_4_TITLE"] = "Die Weltkarte im Kampf"
L["WN67_4_TEXT"] = "Im Kampf geöffnet wird die Karte allein vom Addon bemessen, sodass ein anderes Karten-Addon keinen Fehler wegen einer blockierten Aktion mehr auslösen kann."
L["WN66_1_TITLE"] = "Tooltips wieder so dunkel wie in Classic Era"
L["WN66_1_TEXT"] = "Jeder Tooltip trägt in jedem Look die dunkle Füllung von Era. Die hellere, blauere Füllung des Spiels schien ab dem zweiten Tooltip durch, mit einer Lücke innen am Rand."
L["WN66_2_TITLE"] = "Die Minimap lässt sich im Bearbeitungsmodus wieder verschieben"
L["WN66_2_TEXT"] = "Beim Ziehen im Bearbeitungsmodus bleibt die Minimap sichtbar und ihr neuer Platz wird gespeichert."
L["WN66_3_TITLE"] = "Die Weltkarte behält ihre Größe im Kampf"
L["WN66_3_TEXT"] = "Im Kampf geöffnet ist die Karte so groß wie außerhalb, mit oder ohne Questlog."
L["WN65_1_TITLE"] = "Alle Fenster auf einmal verschieben"
L["WN65_1_TEXT"] = "ClassicUI Forever Windows hat ein Feld Fensterreihe: Ziehst du es, wandern alle Fenster, die sich nebeneinander öffnen, gemeinsam dorthin."
L["WN65_2_TITLE"] = "Tierausbildung rechnet wieder in Trainingspunkten"
L["WN65_2_TEXT"] = "Das Fenster des Tierausbilders zeigt die Trainingspunkte deines Begleiters und was jede Fähigkeit an Punkten kostet, und Ausbilden richtet sich danach, wie in Classic Era."

L["WN64_1_TITLE"] = "Aktionsleisten verblassen lassen"
L["WN64_1_TEXT"] = "Wähle im Bearbeitungsmodus eine Leiste: unter den Einstellungen des Spiels für sie stellst du ein, worauf sie verblasst, oder hakst Nur beim Überfahren zeigen an. Sie wird wieder voll sichtbar, solange die Maus darauf ist oder ein Zauber darauf gezogen wird."
L["WN64_2_TITLE"] = "Fehler bei Namensplaketten behoben"
L["WN64_2_TEXT"] = "Mit den Namensplaketten des Spiels und den Auren eines anderen Addons darauf lösen neue Namensplaketten keinen Lua-Fehler mehr aus."
L["WN64_3_TITLE"] = "Leere Plätze nach dem Zauberbuch"
L["WN64_3_TEXT"] = "Mit ausgeschaltetem Immer Tasten anzeigen erscheinen die leeren Plätze deiner Leisten wieder für einen Zauber oder Gegenstand, den du nach dem Schließen des Zauberbuchs aufnimmst."
L["WN64_4_TITLE"] = "Korrekturen an ClassicUI Forever Windows"
L["WN64_4_TEXT"] = "Sein Kästchen im Bearbeitungsmodus lässt sich wieder anklicken, und die Größe der Weltkarte dort ändert sich gleichmäßig ab der Größe, mit der sie sich öffnet."

L["WN63_1_TITLE"] = "Beute-Tooltips neben dem Gegenstand"
L["WN63_1_TEXT"] = "Im Beutefenster öffnet sich der Tooltip eines Gegenstands neben seinem Symbol, wie in Classic Era, nicht mehr hinter dem rechten Fensterrand."

L["WN62_1_TITLE"] = "Aktionsleisten auseinanderziehen"
L["WN62_1_TEXT"] = "Der Symbolabstand aus dem Bearbeitungsmodus zieht jetzt die Tasten jeder Aktionsleiste auseinander. Bei Aktionsleiste 1 wird das Steinband mit breiter, jede Taste bleibt in ihrer Fassung."
L["WN62_2_TITLE"] = "Geschenke in der Sammlung auspacken"
L["WN62_2_TEXT"] = "Als Geschenk verpackte Reittiere, Haustiere und Spielzeuge lassen sich im klassischen Sammlungsfenster auspacken: wähle eins und klicke auf Auspacken, oder klicke ein verpacktes Spielzeug an."
L["WN62_3_TITLE"] = "Tooltips wie in Classic Era"
L["WN62_3_TEXT"] = "Tooltips im klassischen Aussehen haben den Hintergrund von Classic Era: dieselbe dunkle Farbe und Durchsichtigkeit, wo sie bisher blauer und deckender waren."

L["WN61_1_TITLE"] = "Klarere Fragen zur Größe"
L["WN61_1_TEXT"] = "Die Fragen und Kästchen zur Oberflächengröße nennen die UI-Skalierung des Spiels und den Prozentwert, den sie einstellen, in weniger Worten."
L["WN60_1_TITLE"] = "Klassische Bossfenster"
L["WN60_1_TEXT"] = "Die Bossfenster in Dungeon- und Schlachtzugskämpfen tragen den alten Drachenrahmen, mit der Stufe in ihrem runden Ring und der Zauberleiste neben oder unter dem Fenster. Um die Fenster des Spiels zurückzubekommen, entferne den Haken bei Boss in der Liste Fenster in den Optionen (/fcui) unter Einheitenfenster."
L["WN60_2_TITLE"] = "Qualitätsrahmen ausblenden"
L["WN60_2_TEXT"] = "Getragene Gegenstände im Charakterfenster können ohne den farbigen Rahmen ihrer Qualität erscheinen. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Charakterfenster ein."
L["WN59_1_TITLE"] = "Weniger Arbeit für das Spiel"
L["WN59_1_TEXT"] = "Namensplaketten arbeiten deutlich weniger, wenn du das Ziel wechselst, zauberst, Auren bekommst oder verlierst oder zwischen anderen Spielern stehst. Auch Ziel- und Fokusfenster und die Wer-Liste tun im Hintergrund weniger."
L["WN58_1_TITLE"] = "Era-Ortsmarkierungen"
L["WN58_1_TEXT"] = "Revantusk und Burg Cenarius erscheinen auf den Kontinentkarten erst, wenn du ihre Gegend erkundet hast, wie in Classic Era."
L["WN57_1_TITLE"] = "Taschen zeigen per Klick"
L["WN57_1_TEXT"] = "Mit Taschenleiste: nur Rucksack zeigt ein Strg-Klick auf den Rucksack die übrigen Taschen oder klappt sie wieder ein; der Pfeil daneben ist weg. Taschen zeigen mit wählt einen anderen Klick. Zum Einschalten wähle Taschenleiste: nur Rucksack in den Optionen (/fcui) unter Taschen."
L["WN57_2_TITLE"] = "Schlüsselbundgrafik ausblenden"
L["WN57_2_TEXT"] = "Schlüsselbundgrafik ausblenden räumt jetzt auch den Platz des Schlüsselbunds auf der klassischen Leiste und ersetzt Auch Schlüsselbundgrafik ausblenden, deine Wahl bleibt erhalten. Es ist standardmäßig aus; schalte es in den Optionen (/fcui) unter Taschen ein."
L["WN57_3_TITLE"] = "Taschen ohne Klassische Leiste"
L["WN57_3_TEXT"] = "Mit ausgeschalteter Klassischer Leiste sind Optionen, denen die eigene Taschenleiste des Spiels nicht folgen kann, ausgegraut, und ihr Tooltip sagt, warum."
L["WN56_1_TITLE"] = "Schnelleres Eigenes Design"
L["WN56_1_TEXT"] = "Ein anderer Look oder ein Teil unter Mit Thema lässt das Spiel nicht mehr stocken, und ein abgewählter Teil bekommt die Farben des Spiels zurück. Eigenes Design ist standardmäßig aus; schalte es in den Optionen (/fcui) unter Aussehen ein."
L["WN55_1_TITLE"] = "Leistentextur"
L["WN55_1_TEXT"] = "Unter Einheitenfenster wählst du die Leistentextur der Gesundheits- und Manaleisten: Klassisch, jetzt glatter gezeichnet, Schlachtzugsfenster, Einfarbig oder Fertigkeitsleiste."
L["WN55_2_TITLE"] = "Shop-Taste"
L["WN55_2_TEXT"] = "Die Shop-Taste kann in einem eigenen Rahmen im 1.x-Mikromenü stehen. Sie ist standardmäßig ausgeblendet: Um sie zu zeigen, entferne den Haken bei Shop unter Mikrotasten ausblenden auf der Seite Aktionsleisten der Optionen (/fcui)."
L["WN55_3_TITLE"] = "Zauberbuch-Taste"
L["WN55_3_TEXT"] = "Die Zauberbuch-Taste im Mikromenü bleibt gedrückt, solange das Zauberbuch deine Zauber zeigt."
L["WN55_4_TITLE"] = "Fehlerbehebungen"
L["WN55_4_TEXT"] = "Der Tooltip der Sozial-Taste sagt Sozial, und ein langer Fenstertitel behält die Enden seines Titelschilds."
L["WN54_1_TITLE"] = "Flüssigere Optionen"
L["WN54_1_TEXT"] = "Das Ändern einer Option ruckelt nicht mehr: Nur die Teile der Oberfläche, die diese Option betrifft, werden neu angeordnet."
L["WN54_2_TITLE"] = "Mikromenü"
L["WN54_2_TEXT"] = "Ausgeblendete Mikrotasten bleiben ausgeblendet, eine einzelne übrige Taste steht am Ende der Reihe, und die Reihe sitzt mittig auf der Leiste ohne Lücke in ihrem Boden."
L["WN54_3_TITLE"] = "Minikarte in Instanzen"
L["WN54_3_TEXT"] = "Mit Minikarte drehen zeigen Instanzen keinen zweiten großen Ring mehr um die Minikarte."
L["WN54_4_TITLE"] = "Behausungstaste"
L["WN54_4_TEXT"] = "Die Behausungstaste im Mikromenü hat jetzt einen 1.x-Rahmen wie die anderen."
L["WN54_5_TITLE"] = "Korrekturen"
L["WN54_5_TEXT"] = "Nach einem Neuladen im Kampf erscheint der Rahmen der Erfahrungsleiste des Spiels nicht mehr über der 1.x-Leiste, und eine im Bearbeitungsmodus gespeicherte Fenstergröße schiebt kein Fenster mehr über den Bildschirmrand hinaus, etwa eine große Weltkarte."
L["WN53_1_TITLE"] = "Feinere Designteile"
L["WN53_1_TEXT"] = "Unter Eigenes Design ist die Liste Mit Thema in feinere Teile aufgeteilt, etwa Zauberleisten, Namensplaketten, das Mikromenü und Menüs, damit du jedes davon im klassischen Look lassen kannst. Eigenes Design ist standardmäßig aus; schalte es in den Optionen (/fcui) unter Aussehen ein."
L["WN53_2_TITLE"] = "Rechte Aktionsleisten"
L["WN53_2_TEXT"] = "Mit ausgeschalteter Klassischer Leiste und einer im Bearbeitungsmodus vergrößerten Minikarte schrumpfen die Aktionsleisten 4 und 5 rechts nicht mehr auf etwa zwei Drittel; sie werden nur so weit kleiner, wie der Platz unter der Minikarte es verlangt."
L["WN53_3_TITLE"] = "Eigene Farbe"
L["WN53_3_TEXT"] = "Ein Klick außerhalb der Farbauswahl behält die gewählte Farbe; Abbrechen oder Escape macht sie weiterhin rückgängig."
L["WN53_4_TITLE"] = "Design-Korrekturen"
L["WN53_4_TEXT"] = "Färbt das Design die Fenster des Spiels, blitzen sie beim Öffnen nicht mehr in ihren eigenen Farben auf, und die roten Knöpfe des Spielmenüs zeigen ihre Enden richtig. Fenster anderer Addons behalten ihren eigenen Look; um sie mitzufärben, schalte Andere Addons in der Liste Mit Thema ein, in den Optionen (/fcui) unter Aussehen."
L["WN52_1_TITLE"] = "Ehrenabzeichen"
L["WN52_1_TEXT"] = "Spieler-, Ziel- und Fokusfenster können das Ehrenstufen-Abzeichen des Spiels anstelle des 1.x-Fraktionswappens zeigen. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Einheitenfenster ein."
L["WN52_2_TITLE"] = "Chat-Reiter beim Überfahren"
L["WN52_2_TEXT"] = "Mit Chat-Reitern beim Überfahren erscheinen nur die Reiter des Chatfensters unter der Maus: die angedockten Fenster gemeinsam, ein herausgezogenes Fenster für sich."
L["WN52_3_TITLE"] = "Gruppensuche-Auge"
L["WN52_3_TEXT"] = "An Minikarte ausrichten für das Gruppensuche-Auge ist nicht mehr in den Optionen; es bleibt in den Einstellungen des Auges im Bearbeitungsmodus."
L["WN52_4_TITLE"] = "Gruppensuche-Auge"
L["WN52_4_TEXT"] = "An Minikarte ausrichten für das Gruppensuche-Auge ist aus den Optionen in sein Feld Gruppensuche in ClassicUI Forever Fenster (Bearbeitungsmodus) gewandert, unter Minikarte. Das Feld bleibt, solange das Auge nicht am Rand steht, damit du es wieder einschalten kannst."
L["WN52_5_TITLE"] = "Tooltip von Schadensblitz"
L["WN52_5_TEXT"] = "Der Tooltip von Schadensblitz sagt, dass das Rot auf der Gesundheitsleiste des Spielerfensters erscheint. Schadensblitz ist standardmäßig aus; schalte es in den Optionen (/fcui) unter Einheitenfenster ein."
L["WN51_1_TITLE"] = "Meisterschaft und Vielseitigkeit"
L["WN51_1_TEXT"] = "Die Werte im Charakterfenster zeigen Meisterschaft und Vielseitigkeit unter Allgemein."
L["WN51_2_TITLE"] = "Berufsfenster"
L["WN51_2_TEXT"] = "Die Wahl der Erweiterung steht jetzt im Filtermenü. Das Fenster öffnet sich dort, wo die anderen Fenster des Spiels stehen, ohne Lücke nach dem Zauberbuch, und sein unterer Rand verläuft unter den Herstellen-Knöpfen."
L["WN51_3_TITLE"] = "Optionen von Eine Tasche"
L["WN51_3_TEXT"] = "Die Optionen unter Eine Tasche ändern nur die Taschenfenster des Addons und sind daher ausgegraut, solange Taschenfenster aus ist. Um sie zu nutzen, schalte es in den Optionen (/fcui) unter Taschen ein."
L["WN51_4_TITLE"] = "Reiter"
L["WN51_4_TEXT"] = "Im Berufs- und im Talentfenster zeigt der gewählte Reiter seine ganze Fläche, und die anderen Reiter zeigen kein schwarzes Band mehr."
L["WN50_1_TITLE"] = "Mit Textur"
L["WN50_1_TEXT"] = "Mit Textur, das die Textur der Grafik in der Farbe des Themas behält, färbt jetzt ganze Fenster, nicht nur ihr Metall: den Stein von Taschen und Reitern, die Ränder von Such- und Eingabefeldern und die Seitenpfeile des Zauberbuchs, wobei ein nutzbarer Pfeil heller ist als ein verbrauchter. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Aussehen ein."
L["WN50_2_TITLE"] = "Themen auf den Fenstern des Spiels"
L["WN50_2_TEXT"] = "Themen färben auch die eigene Grafik des Spiels, die in den vom Addon umgestalteten Fenstern bleibt: die Reiter des Kontaktfensters, Bildlaufleisten, Suchfelder, Auswahllisten wie die Statuswahl, das Geldfeld, die Spaltenköpfe der Gildenliste, das Chatfeld der Communitys und den Schlachtzugreiter."
L["WN50_3_TITLE"] = "Bronze auf Retail"
L["WN50_3_TEXT"] = "Das Bronze-Thema färbt jetzt auch die eigene Fenstergrafik des Spiels, die auf Retail silbern ist, wie es die anderen Themen tun."
L["WN50_4_TITLE"] = "Hilfeknöpfe ausblenden"
L["WN50_4_TEXT"] = "Blendet die Hilfeknöpfe des Spiels aus, das i oben links an Fenstern wie Karte, Berufen und Zauberbuch, und die Tutorialtipps, die sie öffnen. Standardmäßig an; schalte es in den Optionen (/fcui) unter Sonstiges aus."
L["WN50_5_TITLE"] = "Wer-Seitenreiter ausblenden"
L["WN50_5_TEXT"] = "Die Gruppensuche kann ihren Wer-Seitenreiter weglassen, sodass Wer nur über das Kontaktfenster erreichbar ist. An für neue Installationen; wenn du das Addon schon genutzt hast, schalte es in den Optionen (/fcui) unter Kontakte ein."
L["WN50_6_TITLE"] = "Fehlerbehebungen"
L["WN50_6_TEXT"] = "Der Porträtring des Zauberbuchs nimmt das Bronze-Thema an, statt silbern zu bleiben, und ein Seitenpfeil, der wieder blättern kann, behält nicht mehr seine verbrauchte Farbe, bis du woanders klickst. Namensplaketten zeigen den Totenkopf für freundliche Einheiten unbekannter Stufe, wie der Zielrahmen. Der innere Rand auf den Reitern Freunde und Schlachtzug des Kontaktfensters die Farbe des Themas an, und ein Fehler, den das Thema im Kampf auslösen konnte, ist behoben."
